/* Stage03-C1 — exact-position card must span the whole subgroup row.
   Without this, CSS Grid auto-placement puts the card back into the narrow label column. */
.catalog-color-subgroup > .catalog-sku-card {
  grid-column: 1 / -1;
  width: 100%;
  min-width: 0;
  margin-top: 4px;
}
